import{c as t,Q as s,j as n,m as l}from"./chunks/framework.DOi4mjdC.js";const p="/assets/zh-cn_image_0000002410305297.DbFnnljS.png",e="/assets/%E4%BC%98%E5%8C%96%E7%82%B9%E4%B8%80%E7%A4%BA%E6%84%8F%E5%9B%BE.BdQGwqSr.png",i="/assets/%E4%BC%98%E5%8C%96%E7%82%B9%E4%BA%8C%E7%A4%BA%E6%84%8F%E5%9B%BE.BGoWsUT-.png",o="/assets/%E4%BC%98%E5%8C%96%E7%82%B9%E4%B8%89%E7%A4%BA%E6%84%8F%E5%9B%BE.CCKnBnpB.png",c="/assets/zh-cn_image_0000002376979814.4oGZuZfw.png",q=JSON.parse('{"title":"Matmul高阶API使能L2 Cache切分","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul高阶API使能L2 Cache切分","slug":"matmul高阶api使能l2-cache切分"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能L2-Cache切分.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能L2-Cache切分.md"}'),u={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能L2-Cache切分.md"};function r(m,a,h,d,g,_){return s(),n("div",null,[...a[0]||(a[0]=[l('<h1 id="matmul高阶api使能l2-cache切分" tabindex="-1">Matmul高阶API使能L2 Cache切分 <a class="header-anchor" href="#matmul高阶api使能l2-cache切分" aria-label="Permalink to &quot;Matmul高阶API使能L2 Cache切分&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例呈现了在Matmul计算过程中，输入和输出的数据总量超过L2 Cache大小时，通过L2 Cache数据切分对算子性能的提升效果。使能L2 Cache切分的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_l2cache" target="_blank" rel="noreferrer">L2 Cache切分的算子样例</a>。</p><p>本案例使用的AI处理器的L2 Cache大小为192MB，L2 Cache纯读带宽约为GM的3到4倍，两者之间存在较大差距。在搬入或搬出相同数据量的情况下，访问L2 Cache内的数据比访问GM更快。若数据无法命中L2 Cache，即需要访问的数据不在L2 Cache内，导致需要访问GM进行读写，带宽利用效率较低，最终算子搬入或搬出数据成为算子整个运行过程的性能瓶颈。</p><ul><li><p>使能L2 Cache切分的适用场景</p><p>输入和输出的数据量超过L2 Cache的大小。</p></li></ul><p>本案例的算子规格如下：</p><p><strong>表 1</strong> 算子规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;输入&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;a&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;30720, 1024&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;b&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;4096, 1024&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>使用msProf工具获取<a href="./../../性能分析/获取性能数据.html#section17259539153513">算子仿真流水图</a>和<a href="./../../性能分析/获取性能数据.html#section17953123893415">上板Profiling</a>数据。因为L2 Cache切分功能主要利用带宽更大的L2 Cache，减少MTE2数据搬运开销，所以重点分析MTE2的流水。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><p>当前案例基于Tiling全量常量化进一步优化，Tiling全量常量化请参考<a href="./Matmul高阶API使能Tiling全量常量化.html">Matmul高阶API使能Tiling全量常量化</a>案例。优化前的Profiling数据如下，C列的aic_time是867us，K列的aic_mte2_time是861.9us，MTE2占比为99%，MTE2数据搬运是当前算子性能的瓶颈。</p><p><img src="'+p+'" alt=""></p><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><ul><li><p>优化点一：调整切块大小和计算次数</p><ul><li>优化前，输入数据不进行切分，所有核一次计算全部数据。如下图所示，图中数字表示核id，24个核一次计算A和B矩阵的所有数据。</li><li>优化后，输入数据被切分多次，所有核分多次计算，每个核单次计算只依赖切分后的数据量。L2 Cache切分方案确保单次计算的数据都在L2 Cache缓存中，搬运输入数据的效率更高。</li></ul><p><strong>图 1</strong> 优化点一示意图<br><img src="'+e+'" alt="" title="优化点一示意图"></p></li><li><p>优化点二：选择拖尾较小的L2 Cache切分方案</p><p>结合<a href="./../../SIMD算子性能优化/Tiling策略/核间负载均衡.html">核间负载均衡</a>的原理，AI处理器的物理核数固定，当数据进行L2 Cache切分之后，可能出现部分核有计算拖尾的情况，即每次所有核总计算量除以每个核单次处理的数据量不能被核数整除，导致每次计算的最后需要部分尾核计算剩余数据。而在尾核计算时，部分核始终处于空闲状态，导致算子的整体性能变差。下图中标黄的数据块就是尾块数据，左边方案由于拖尾，每次计算中0、1、2、3核多执行一次处理剩余数据。为达到全局负载最优，调整拖尾核的位置，如右边方案所示，完成所有计算时，0到7核均多一次数据块的计算。</p><p>在实际场景中，满足切分后的数据量小于L2 Cache大小的前提下，拖尾越小越好。基于这个原则可以确定L2 Cache切分块数。</p><p><strong>图 2</strong> 优化点二示意图<br><img src="'+i+'" alt="" title="优化点二示意图"></p></li><li><p>优化点三：错位分核，减少左右矩阵同地址冲突问题</p><p>同地址冲突：多核并发执行Matmul计算时，如果多核同时访问输入矩阵的相同地址，会导致地址冲突，影响性能。</p><p>在M和N方向，将矩阵数据L2 Cache切分为大数据块， 然后在数据块间错位分核，即将每个数据块依次沿对角线分配给不同的核处理，从而有效减少同地址冲突的问题。比如，在处理同一行的尾块数据0，1，2，3时，如果顺序分配执行的核，多核会同时读同一行左矩阵数据，导致读读冲突。若按照对角线方式分配执行的核，在对角线上的尾块数据被分配给核0，1，2，3计算，多核访问不同行的左矩阵数据，将减少同地址冲突的次数。</p><p><strong>图 3</strong> 优化点三示意图<br><img src="'+o+`" alt="" title="优化点三示意图"></p></li></ul><p>Matmul API使能L2 Cache切分的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_l2cache" target="_blank" rel="noreferrer">L2 Cache切分的算子样例</a>。实现L2 Cache切分的关键步骤如下：</p><ol><li><p>判断是否需要进行L2 Cache切分。如果数据总量超过设定的L2 Cache大小，则计算L2 Cache切分数目。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bool smallDim = mTileNum_ &lt; L1_MIN_UST_DIM &amp;&amp; nTileNum_ &lt; L1_MIN_UST_DIM; </span></span>
<span class="line"><span>if (smallDim || (!EnableL2Tile())) { // 判断计算数据总量是否小于L2Cache阈值     </span></span>
<span class="line"><span>    mL2TileNum_ = mTileNum_;</span></span>
<span class="line"><span>    nL2TileNum_ = nTileNum_;</span></span>
<span class="line"><span>    mL2BlockNum_ = 1;</span></span>
<span class="line"><span>    nL2BlockNum_ = 1;</span></span>
<span class="line"><span>    return; // 不需要切分，提前返回 </span></span>
<span class="line"><span>} </span></span>
<span class="line"><span>InitL2TileTail(); // 计算L2切分</span></span></code></pre></div></li><li><p>基于负载均衡原则，计算L2 Cache切分的份数，m方向L2 Cache切分数：mL2TileNum_，n方向L2 Cache切分数：nL2TileNum_。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int64_t mConflict = INT64_MAX; </span></span>
<span class="line"><span>int64_t nConflict = INT64_MAX; </span></span>
<span class="line"><span>constexpr bool isNMajor = l1N &gt; l1M; // 根据shape大小，判断主维度 </span></span>
<span class="line"><span>for (int64_t i = maxMajor; i &gt;= L1_MIN_UST_DIM; i--) {     </span></span>
<span class="line"><span>    for (int64_t j = maxMinor; j &gt;= minMinor; j--) {         </span></span>
<span class="line"><span>        if (GetTotalSize(j * l1M, i * l1N, k_) &lt;= L2_TILE_THRESHOLD) { // 确保分块小于L2Cache阈值           </span></span>
<span class="line"><span>            uint64_t mConflictTmp = AscendC::Ceil(blockNum_, mL2TileNumTailTmp); // 计算负载冲突值            </span></span>
<span class="line"><span>            uint64_t nConflictTmp = AscendC::Ceil(blockNum_, nL2TileNumTailTmp);            </span></span>
<span class="line"><span>            if (mConflict &gt;= mConflictTmp &amp;&amp; nConflict &gt;= nConflictTmp) { // 若冲突值更小，更新分块数量             </span></span>
<span class="line"><span>                mConflict = mConflictTmp;              </span></span>
<span class="line"><span>                nConflict = nConflictTmp;         </span></span>
<span class="line"><span>                mL2TileNum_ = curMajorDim;                 </span></span>
<span class="line"><span>                nL2TileNum_ = curMinorDim;     </span></span>
<span class="line"><span>            }       </span></span>
<span class="line"><span>         }   </span></span>
<span class="line"><span>     }</span></span>
<span class="line"><span> }</span></span></code></pre></div></li><li><p>错位分核。输入当前数据块的下标，获取按对角线分配的核的下标。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline BlockCoord GetBlockCoord(int64_t tileIdx)    {  </span></span>
<span class="line"><span>    GetCommonTileIndex(tileIdx); </span></span>
<span class="line"><span>    int64_t mTileIdx = newBlockIdx_ % mL2TileNumTmp_;</span></span>
<span class="line"><span>    mTileIdx = mTileIdx + mL2Idx_ * mL2TileNum_;</span></span>
<span class="line"><span>    int64_t nTileIdx = 0;     </span></span>
<span class="line"><span>    if (mL2TileNumTmp_ != 0 &amp;&amp; nL2TileNumTmp_ != 0) {  </span></span>
<span class="line"><span>        int64_t tmp = newBlockIdx_ /CalcLcm(mL2TileNumTmp_, nL2TileNumTmp_);</span></span>
<span class="line"><span>        nTileIdx = (newBlockIdx_ + tmp) % nL2TileNumTmp_;</span></span>
<span class="line"><span>    }      </span></span>
<span class="line"><span>    nTileIdx = nTileIdx + nL2Idx_ * nL2TileNum_;     </span></span>
<span class="line"><span>    return {mTileIdx * l1M, nTileIdx * l1N, 0};</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>设置左右矩阵，根据前序步骤计算的L2 Cache切分数和执行核的下标，循环多次计算Matmul。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L2CacheOpt l2Opt(shapes, blockNum); </span></span>
<span class="line"><span>matmulObj.SetOrgShape(shapes.m, shapes.n, shapes.k);</span></span>
<span class="line"><span>for (int64_t tileIdx = curBlockIdx; tileIdx &lt; l2Opt.GetTileNum(); tileIdx += blockNum) { </span></span>
<span class="line"><span>    auto blockShape = l2Opt.GetBlockShape(tileIdx);  // 获取单次计算L2切分块大小     </span></span>
<span class="line"><span>    if (Get&lt;0&gt;(blockShape) &lt;= 0 ||</span></span>
<span class="line"><span>        Get&lt;1&gt;(blockShape) &lt;= 0){</span></span>
<span class="line"><span>        return;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    auto blockCoord = l2Opt.GetBlockCoord(tileIdx); </span></span>
<span class="line"><span>    // 获取当前执行计算的核的下标blockCoord    </span></span>
<span class="line"><span>    matmulObj.SetTail(Get&lt;0&gt;(blockShape), Get&lt;1&gt;(blockShape), Get&lt;2&gt;(blockShape)); </span></span>
<span class="line"><span>    const auto&amp; offsetCoord = CalcOffset(shapes, blockCoord); // 基于下标计算矩阵偏移    </span></span>
<span class="line"><span>    int64_t offsetA = Get&lt;0&gt;(offsetCoord);</span></span>
<span class="line"><span>    int64_t offsetB = Get&lt;1&gt;(offsetCoord);   </span></span>
<span class="line"><span>    int64_t offsetC = Get&lt;2&gt;(offsetCoord);</span></span>
<span class="line"><span>    matmulObj.SetTensorA(aGlobal[offsetA], false);  </span></span>
<span class="line"><span>    matmulObj.SetTensorB(bGlobal[offsetB], false);  </span></span>
<span class="line"><span>    if (shapes.isBias) {          </span></span>
<span class="line"><span>        matmulObj.SetBias(biasGlobal);    </span></span>
<span class="line"><span>    }  </span></span>
<span class="line"><span>    matmulObj.IterateAll(cGlobal[offsetC]);  // 计算L2切分块 </span></span>
<span class="line"><span>} </span></span>
<span class="line"><span>matmulObj.End();</span></span></code></pre></div></li></ol><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><p>优化后的Profiling数据如下，C列的aic_time为805.6us，相比于优化前，总执行时间降低了约7.1%，MTE2搬运时间降低了约10.7%。</p><p><img src="`+c+'" alt=""></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在Matmul计算数据量超过L2 Cache大小的场景下，可以考虑使能L2 Cache切分，提高L2 Cache命中率，利用L2 Cache高带宽特性提升算子性能。</p>',22)])])}const b=t(u,[["render",r]]);export{q as __pageData,b as default};
